#!/usr/bin/env python
"""Probes for the container types: tuple, set, and dicts with non-string keys (and DynObj truthiness).

Same machinery as ``probes.py`` (each probe runs against upstream and the Rust evaluator); the
entries go to their own corpus file so regenerating it does not touch ``curated.jsonl``.

``python probes_containers.py``                         print the probes that diverge
``python probes_containers.py --write corpus/containers.jsonl``
"""

from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))

from campaign import enc_bindings, py_pair  # noqa: E402
from codec import show  # noqa: E402
from oracle import Oracle  # noqa: E402
from probes import normalise  # noqa: E402

U = "unrestricted"
B = {"a": 1, "s": "hello", "l": [1, 2, 3], "m": {"a": 1, "b": {"c": 2}}, "e": {}, "n": None, "t": ["he", "zz"], "ml": [{"a": 1}, {"a": 2}]}


def blocks(*exprs: str) -> list:
    return [(f"target = {e}", B, U) for e in exprs]


def both(*exprs: str) -> list:
    """Each expression in the restricted evaluator and as an asteval block."""
    return [*exprs, *blocks(*exprs)]


ints = lambda n, lo=-40, hi=80: ", ".join(str((i * 37 + 11) % (hi - lo) + lo) for i in range(n))  # noqa: E731

